# WAR ARENA - Launch Free Window (promotion) - Installer
# All scan/monitor operations are free for everyone until FREE_UNTIL (ISO date),
# then normal billing resumes automatically. Run from project root:
#   powershell -ExecutionPolicy Bypass -File .\install-promotion.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Launch free window installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/pricing/promotion.ts" ""
Write-B64 "src/integration/warRuntime.ts" ""
Write-B64 "src/api/wiredApp.ts" ""
Write-B64 "src/deploy/env.ts" ""
Write-B64 "src/deploy/server.ts" ""
Write-B64 "tests/unit/promotion.test.ts" ""
Write-B64 "tests/integration/wiredApi.test.ts" ""
Write-B64 ".env.example" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Promotion installed. Expected: 987 passed + 1 skipped, 461 guards." -ForegroundColor Green
Write-Host "Set FREE_UNTIL=2026-XX-XX in .env to open the free window." -ForegroundColor Yellow
